//
//  RootListController.swift — Aevon, Settings side.
//
//  Rows come from Root.plist / Window.plist / … generated by
//  tools/gen-settings.py from one table, so the UI and the delivery document
//  can never drift apart.
//
//  Why this class loads the plist itself (0.0.4):
//  `PSListController.specifiers` is a plain property backed by an ivar, and
//  nothing in the framework populates it for a subclass. 0.0.3 only overrode
//  the *readers*, so the ivar stayed nil, the table had zero rows, and Settings
//  showed an empty black page. Every row now comes from an explicit
//  loadSpecifiersFromPlistName: call written back through the setter, which is
//  also what rowsForGroup:/specifierAtIndex: read internally.
//
//  If even that returns nothing, the controller renders one diagnostic group
//  instead of a black page: a blank screen tells the operator nothing, a line
//  of text tells them exactly which path is missing.
//
//  Four rows are real functionality, not placeholders:
//      inject status / version / loads / last load   -> read from state.plist
//      emergency stop (G0) / pause injection (G1)    -> real gate writes
//      清除崩溃计数 / 重载桌面                          -> real actions
//
//  This process is separate from SpringBoard: it stays usable even when the
//  tweak has switched itself off, which is the entire point of the kill switch.
//

import UIKit

@objc(AevonRootListController)
final class RootListController: PSListController {

    // MARK: Lifecycle

    override func viewDidLoad() {
        super.viewDidLoad()
        installRows()
    }

    override func viewWillAppear(_ animated: Bool) {
        super.viewWillAppear(animated)
        installRows()   // no-op once rows exist; the safety net for odd timings
        reload()        // status / gate rows re-read their values
    }

    // MARK: Rows

    /// Loads Root.plist into the `specifiers` ivar exactly once.
    ///
    /// Three attempts, cheapest first, and the last one always succeeds:
    ///   1. the classic two-argument loader (present on every iOS that has
    ///      Preferences.framework at all)
    ///   2. the bundle-explicit overload, guarded by responds(to:) because it
    ///      is newer — an unguarded call would be an unrecognized selector
    ///   3. one diagnostic group, so the page is never blank
    private func installRows() {
        if let existing = specifiers, existing.count > 0 { return }

        let bundle = Bundle(for: RootListController.self)

        var list = loadSpecifiers(fromPlistName: "Root", target: self)
        if (list?.count ?? 0) == 0,
           responds(to: NSSelectorFromString("loadSpecifiersFromPlistName:target:bundle:")) {
            list = loadSpecifiers(fromPlistName: "Root", target: self, bundle: bundle)
        }
        if (list?.count ?? 0) == 0 {
            list = diagnosticRows(bundle: bundle)
        }

        specifiers = list ?? NSMutableArray()
        Log.write("prefs: \(specifiers?.count ?? 0) rows, bundle=\(bundle.bundlePath)")
    }

    /// One group cell with a readable explanation. Uses only emptyGroup
    /// and string properties — no factory call whose cell-type constant could
    /// differ across iOS versions, so this path cannot itself fail.
    private func diagnosticRows(bundle: Bundle) -> NSMutableArray {
        let plist = bundle.path(forResource: "Root", ofType: "plist") ?? "缺失"
        let group = PSSpecifier.emptyGroup()
        group.setProperty("界面未能加载", forKey: "label")
        group.setProperty("""
            这不是崩溃，是面板文件没被读到。请把这段文字连同 /var/mobile/Aevon.log 一起反馈。
            bundle: \(bundle.bundlePath)
            Root.plist: \(plist)
            """, forKey: "footerText")

        let list = NSMutableArray()
        list.add(group)
        return list
    }

    /// Live rows re-read through readPreferenceValue(_:), so a full plist
    /// reload is unnecessary — and would rebuild the ivar we just filled.
    private func refreshLiveRows() {
        reload()
    }

    // MARK: Gate switches

    override func readPreferenceValue(_ specifier: PSSpecifier) -> Any? {
        let key = (specifier.property(forKey: "key") as? String) ?? ""
        let state = Gate.readState()

        switch key {
        case "@status.state":   return Gate.statusText
        case "@status.version": return (state["version"] as? String) ?? "未加载"
        case "@status.loads":   return (state["attempts"] as? NSNumber)?.stringValue ?? "—"
        case "@status.last":    return Gate.timeText((state["lastLoad"] as? NSNumber)?.doubleValue ?? 0)
        case "@status.log":     return Aevon.logPath
        case "!gate.panic":     return Gate.panicActive
        case "!gate.disabled":  return Gate.disabledActive
        default:                return super.readPreferenceValue(specifier)
        }
    }

    override func setPreferenceValue(_ value: Any?, specifier: PSSpecifier) {
        if let key = specifier.property(forKey: "key") as? String {
            let on = (value as? NSNumber)?.boolValue ?? false

            switch key {
            case "!gate.panic":
                Gate.setPanic(on)
                Log.write("settings: G0 emergency stop -> \(on ? "on" : "off")")
                refreshLiveRows()
                return
            case "!gate.disabled":
                Gate.setDisabled(on, reason: "manual:settings")
                Log.write("settings: G1 pause injection -> \(on ? "on" : "off")")
                refreshLiveRows()
                return
            default:
                break
            }
        }
        super.setPreferenceValue(value, specifier: specifier)
    }

    // MARK: Actions

    @objc func clearAttempts(_ specifier: PSSpecifier) {
        Gate.resetAttempts()
        Gate.request(Aevon.commandReset)   // SpringBoard clears its own copy too
        refreshLiveRows()
        alert("已清除", "崩溃计数归零。如果之前是自动停用，点「重载桌面（应用闸门变更）」即可重新加载。")
    }

    @objc func respring(_ specifier: PSSpecifier) {
        let sheet = UIAlertController(
            title: "重载桌面",
            message: "桌面会重启约 5–10 秒。若 Aevon 已停止，重启后不会加载任何 hook。",
            preferredStyle: .alert)
        sheet.addAction(UIAlertAction(title: "取消", style: .cancel, handler: nil))
        sheet.addAction(UIAlertAction(title: "重载", style: .destructive) { [weak self] _ in
            self?.requestRespring()
        })
        present(sheet, animated: true)
    }

    private func requestRespring() {
        // Preferred path: the tweak lives in SpringBoard and is not sandboxed.
        Gate.request(Aevon.commandRespring)

        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) { [weak self] in
            // Still here means the in-process request did not land.
            if !Spawn.respring() {
                self?.alert("无法自动重载",
                            "当前环境不允许从设置里重启桌面。请用越狱工具自带的重启按钮，或手动注销一次。")
            }
        }
    }

    private func alert(_ title: String, _ message: String) {
        let sheet = UIAlertController(title: title, message: message, preferredStyle: .alert)
        sheet.addAction(UIAlertAction(title: "好", style: .default, handler: nil))
        present(sheet, animated: true)
    }
}

// PreferenceLoader finds this class through the *string* in its plist, which
// neither the compiler nor the linker can see. One direct reference keeps the
// class through -dead_strip; without it a future optimisation pass could drop
// the only thing that makes the entry tappable.
private let aevonRootListControllerKeepAlive: AnyClass = RootListController.self
